package com.example.roseledger.data.model

import androidx.room.Entity
import androidx.room.PrimaryKey
import java.util.Date

/**
 * Represents a single expense record in the database.
 *
 * @param id The unique identifier for the expense, auto-generated by the database.
 * @param amount The amount of the expense.
 * @param category The category of the expense.
 * @param description A brief description of the expense.
 * @param date The date when the expense occurred.
 * */
@Entity(tableName = "expenses")
data class Expense(
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val amount: Double,
    val category: String,
    val description: String,
    val date: Date
)
